// the bytes exist — the length of a body has to be known before it is written,
// because a length whose own width moves cannot be patched in place.
inline int64_t TableLebBytes( uint64_t v )
{
    int64_t n = 1;
    while ( v >= 0x80 ) { v >>= 7; n++; }
    return n;
}

