// — form byte, seven reserved zero bytes, the LAYOUT HASH at 8, body at 16 —
// then the layout behind its u32 length, then the records to the end of it.
constexpr int64_t ArchiveConfigFixedMeasure( int64_t count )
{
    return kTableFixedHeaderBytes + 4 + ArchiveConfigFixedLayoutBytes + count * ArchiveConfigFixedRecordBytes;
}

inline int64_t ArchiveConfigFixedSave( const ArchiveConfig * values, int64_t count, uint8_t * buffer, int64_t capacity )
{
    const int64_t need = ArchiveConfigFixedMeasure( count );
    if ( count < 0 || buffer == NULL || capacity < need ) { return -1; }
    memset( buffer, 0, (size_t) kTableFixedHeaderBytes ); // the seven reserved bytes, and the rest of the header
    buffer[0] = kTableFixedForm;
    TableFixedPut64( buffer + kTableFixedHashAt, ArchiveConfigFixedHash );
    TableFixedPut32( buffer + kTableFixedHeaderBytes, (uint32_t) ArchiveConfigFixedLayoutBytes );
    memcpy( buffer + kTableFixedHeaderBytes + 4, ArchiveConfigFixedLayout, (size_t) ArchiveConfigFixedLayoutBytes );
    uint8_t * at = buffer + kTableFixedHeaderBytes + 4 + ArchiveConfigFixedLayoutBytes;
    for ( int64_t k = 0; k < count; ++k )
    {
        TableFixedPut64( at, ArchiveConfigFixedHash );
        memset( at + 8, 0, (size_t) ArchiveConfigFixedBodyBytes ); // the prefill's zeros
        ArchiveConfigFixedWriteBody( at + 8, values[k] );
        at += ArchiveConfigFixedRecordBytes;
    }
    return need;
}

